mapper.select:
SELECT id
FROM chapter_publish_event
WHERE status = 'PENDING'
  AND next_attempt_time <= #{now}
ORDER BY id
LIMIT #{limit}

mapper.insert:
INSERT IGNORE INTO user_notification
    (user_id, notification_type, book_id, author_id, chapter_id, book_name, chapter_name, create_time)
SELECT follower.user_id, 'NEW_CHAPTER', #{bookId}, #{authorId}, #{chapterId},
       #{bookName}, #{chapterName}, CURRENT_TIMESTAMP
FROM (
    SELECT user_id FROM user_bookshelf WHERE book_id = #{bookId}
    UNION
    SELECT user_id FROM user_author_follow WHERE author_id = #{authorId}
) follower
